import{c as o,Q as e,j as r,m as a}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Build on Priors: Vision-Language-Guided Neuro-Symbolic Imitation Learning for Data-Efficient Real-World Robot Manipulation","description":"","frontmatter":{"url":"https://arxiv.org/abs/2604.03759","title":"Build on Priors: Vision-Language-Guided Neuro-Symbolic Imitation Learning for Data-Efficient Real-World Robot Manipulation","archived_date":"2026-07-12","arxiv_id":"2604.03759","authors":["Pierrick Lorang","Johannes Huemer","Timothy Duggan","Kai Goebel","Patrik Zips","Matthias Scheutz"],"domain":"neuro-symbolic-robot-policy","published_date":"2026-04-04","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-04-04-neurosymbolic-imitation-learning-priors-2604-03759.md","filePath":"research/papers/2026-04-04-neurosymbolic-imitation-learning-priors-2604-03759.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-04-04-neurosymbolic-imitation-learning-priors-2604-03759.md"};function t(l,i,s,u,d,c){return e(),r("div",null,[...i[0]||(i[0]=[a('<h1 id="build-on-priors-vision-language-guided-neuro-symbolic-imitation-learning" tabindex="-1">Build on Priors: Vision-Language-Guided Neuro-Symbolic Imitation Learning <a class="header-anchor" href="#build-on-priors-vision-language-guided-neuro-symbolic-imitation-learning" aria-label="Permalink to &quot;Build on Priors: Vision-Language-Guided Neuro-Symbolic Imitation Learning&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>本文提出一套 neuro-symbolic 框架，用 1–30 筆未標註示範即可教機器人完成操作任務， 自動生成符號規劃領域與控制策略，免除人工領域工程。</p><p><strong>方法：</strong></p><ol><li>將示範切分為技能片段，用 VLM 分類技能、辨識等價狀態</li><li>建構狀態轉移圖，透過 Answer Set Programming solver 轉為 PDDL 規劃領域</li><li>策略在「控制參考層級」而非原始致動器訊號上訓練，學習更平滑</li><li>資料增強技術：把單一示範投影到場景中其他物件上</li></ol><p><strong>驗證：</strong> 主要在真實工業堆高機（forklift）測試，並在 Kinova Gen3 機械臂上以兩個 benchmark 額外驗證。作者稱此為邁向「可擴展、資料高效、免專家、可解釋」神經符號機器人的實務路徑。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p><code>neurosymbolic</code> / <code>neuro-symbolic</code> 關鍵詞在 workspace 自有題庫命中 <strong>0 次</strong>，與同批收錄的 2604.02812（VLM→Behavior Tree）共同構成「neuro-symbolic robot policy」子領域的第二個接地 來源，皆聚焦「用少量監督生成可解釋符號結構取代黑箱端到端策略」這條技術路線。</p>',8)])])}const g=o(n,[["render",t]]);export{p as __pageData,g as default};
